// HMAC-SHA256 built on the pure-JS SHA-256 in sha256.mjs (RFC 2104).

import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

export function hmacSha256(keyBytes, messageBytes) {
  let key = keyBytes;
  if (key.length > BLOCK_SIZE) {
    key = sha256(key);
  }
  const paddedKey = new Uint8Array(BLOCK_SIZE);
  paddedKey.set(key);

  const inner = new Uint8Array(BLOCK_SIZE + messageBytes.length);
  const outerPad = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    inner[i] = paddedKey[i] ^ 0x36;
    outerPad[i] = paddedKey[i] ^ 0x5c;
  }
  inner.set(messageBytes, BLOCK_SIZE);

  const innerHash = sha256(inner);

  const outer = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outer.set(outerPad);
  outer.set(innerHash, BLOCK_SIZE);

  return sha256(outer);
}

