// Base64url encoding/decoding without padding, matching the JWT spec (RFC 7515)
// and Python's base64.urlsafe_b64encode/urlsafe_b64decode behavior.

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

const REV = new Map();
for (let i = 0; i < ALPHABET.length; i++) {
  REV.set(ALPHABET[i], i);
}

export function base64urlEncode(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    const n = (b0 << 16) | (b1 << 8) | b2;
    out += ALPHABET[(n >> 18) & 63];
    out += ALPHABET[(n >> 12) & 63];
    if (i + 1 < bytes.length) out += ALPHABET[(n >> 6) & 63];
    if (i + 2 < bytes.length) out += ALPHABET[n & 63];
  }
  return out;
}

export function base64urlDecode(str) {
  // Python's urlsafe_b64decode requires correct padding; add it back.
  let s = str;
  const rem = s.length % 4;
  if (rem === 1) {
    throw new Error('Invalid base64url input length');
  }
  if (rem !== 0) {
    s += '='.repeat(4 - rem);
  }
  const bytes = [];
  for (let i = 0; i < s.length; i += 4) {
    const c0 = REV.get(s[i]);
    const c1 = REV.get(s[i + 1]);
    const c2 = s[i + 2] === '=' ? 0 : REV.get(s[i + 2]);
    const c3 = s[i + 3] === '=' ? 0 : REV.get(s[i + 3]);
    if (c0 === undefined || c1 === undefined || c2 === undefined || c3 === undefined) {
      throw new Error('Invalid base64url character');
    }
    const n = (c0 << 18) | (c1 << 12) | (c2 << 6) | c3;
    bytes.push((n >> 16) & 0xff);
    if (s[i + 2] !== '=') bytes.push((n >> 8) & 0xff);
    if (s[i + 3] !== '=') bytes.push(n & 0xff);
  }
  return new Uint8Array(bytes);
}

