// JSON serialization matching Python's json.dumps(obj, separators=(',', ':'))
// with the default ensure_ascii=True, as used by python-jose when encoding.

function escapeString(str) {
  let out = '"';
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    switch (ch) {
      case '"': out += '\\"'; continue;
      case '\\': out += '\\\\'; continue;
      case '\b': out += '\\b'; continue;
      case '\f': out += '\\f'; continue;
      case '\n': out += '\\n'; continue;
      case '\r': out += '\\r'; continue;
      case '\t': out += '\\t'; continue;
      default: break;
    }
    if (cp < 0x20 || cp > 0x7e) {
      // ensure_ascii=True: escape everything outside printable ASCII as \uXXXX
      // (astral characters are emitted as UTF-16 surrogate pairs).
      const units = ch.length === 2 ? [ch.charCodeAt(0), ch.charCodeAt(1)] : [ch.charCodeAt(0)];
      for (const u of units) {
        out += '\\u' + u.toString(16).padStart(4, '0');
      }
    } else {
      out += ch;
    }
  }
  out += '"';
  return out;
}

export function dumpsCompact(value) {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'string') return escapeString(value);
  if (typeof value === 'number') {
    if (Number.isInteger(value)) return String(value);
    return String(value);
  }
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (Array.isArray(value)) {
    return '[' + value.map(dumpsCompact).join(',') + ']';
  }
  if (typeof value === 'object') {
    const parts = [];
    for (const [k, v] of Object.entries(value)) {
      parts.push(escapeString(k) + ':' + dumpsCompact(v));
    }
    return '{' + parts.join(',') + '}';
  }
  throw new TypeError(`Object of type ${typeof value} is not JSON serializable`);
}

