// Minimal re-implementation of the python-jose JWT behavior used by the
// original script: jwt.encode (HS256 default), jwt.get_unverified_claims,
// and jwt.get_unverified_header.

import { base64urlEncode, base64urlDecode } from './base64url.mjs';
import { utf8Encode, utf8Decode } from './utf8.mjs';
import { hmacSha256 } from './hmacSha256.mjs';
import { dumpsCompact } from './jsonUtil.mjs';

