// Python-style repr() rendering for the values printed by the original
// script (dicts of str -> str), so console.log output matches Python's
// print() character for character.

// Approximation of Python's str.isprintable(): characters in Unicode general
// categories Other (C*) and Separator (Z*, except ASCII space) are escaped.
// For the ASCII range this is exact; non-ASCII printable characters (letters,
// CJK, symbols, ...) are emitted as-is, matching CPython for typical input.
function isPrintable(cp) {
  if (cp === 0x20) return true;
  if (cp < 0x20 || (cp >= 0x7f && cp <= 0xa0)) return false;
  if (cp === 0xad) return false; // soft hyphen (Cf)
  return true;
}

function hexEscape(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

export function reprStr(str) {
  // CPython prefers single quotes, switching to double quotes only when the
  // string contains a single quote but no double quote.
  const hasSingle = str.includes("'");
  const hasDouble = str.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (!isPrintable(cp)) {
      out += hexEscape(cp);
    } else {
      out += ch;
    }
  }
  out += quote;
  return out;
}

export function reprDict(obj) {
  const parts = [];
  for (const [k, v] of Object.entries(obj)) {
    parts.push(reprStr(k) + ': ' + reprStr(String(v)));
  }
  return '{' + parts.join(', ') + '}';
}

