// Minimal argument parser mimicking Python's argparse for this script's
// interface: two required string options, --payload and --secret, plus -h.

import { basename } from 'node:path';

function prog() {
  return basename(process.argv[1] || 'test8.mjs');
}

const USAGE_ARGS = '[-h] --payload PAYLOAD --secret SECRET';

function printUsage(stream) {
  stream.write(`usage: ${prog()} ${USAGE_ARGS}\n`);
}

function errorExit(message) {
  printUsage(process.stderr);
  process.stderr.write(`${prog()}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  printUsage(process.stdout);
  process.stdout.write(`\noptions:\n`);
  process.stdout.write(`  -h, --help         show this help message and exit\n`);
  process.stdout.write(`  --payload PAYLOAD\n`);
  process.stdout.write(`  --secret SECRET\n`);
  process.exit(0);
}

const OPTION_DEST = {
  '--payload': 'payload',
  '--secret': 'secret',
};

export function parseArgs(argv) {
  const result = { payload: undefined, secret: undefined };
  const unrecognized = [];
  const seen = new Set();

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      printHelp();
    }

    let name = arg;
    let inlineValue = null;
    const eq = arg.indexOf('=');
    if (arg.startsWith('--') && eq !== -1) {
      name = arg.slice(0, eq);
      inlineValue = arg.slice(eq + 1);
    }

    const dest = OPTION_DEST[name];
    if (dest !== undefined) {
      seen.add(dest);
      if (inlineValue !== null) {
        result[dest] = inlineValue;
        i += 1;
      } else if (i + 1 < argv.length) {
        result[dest] = argv[i + 1];
        i += 2;
      } else {
        errorExit(`argument ${name}: expected one argument`);
      }
    } else {
      unrecognized.push(arg);
      i += 1;
    }
  }

  if (unrecognized.length > 0) {
    errorExit(`unrecognized arguments: ${unrecognized.join(' ')}`);
  }

  const missing = [];
  if (!seen.has('payload')) missing.push('--payload');
  if (!seen.has('secret')) missing.push('--secret');
  if (missing.length > 0) {
    errorExit(`the following arguments are required: ${missing.join(', ')}`);
  }

  return result;
}

